    # Commit point not reached: only roll the file back when it may
    # have landed (a failed ledger append, or a partial initial
    # write), then release every handle minted for this change.
    if os.path.exists(path):
        if previous is None:
            try:
                os.unlink(path)
            except OSError:
                pass
