"""Fake external KMS/HSM provider for keymgr black-box testing.

Persists its handle registry to <data_dir>/fakekms-registry.json so separate
CLI processes see the same "backend". A load sentinel file and a delete log
let tests assert when the factory was imported and which handles were
deleted. Failure injection is driven by environment variables.
"""

import base64
import json
import os

from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import rsa

_SENTINEL = os.environ.get("FAKEKMS_SENTINEL", "/tmp/fakekms-loaded")
_REG = "fakekms-registry.json"
_DELETE_LOG = "fakekms-deletes.log"


def _fail_for(op):
    failed = [x for x in os.environ.get("FAKEKMS_FAIL", "").split(",") if x]
    return op in failed


class FakeKMS:
    provider_id = os.environ.get("FAKEKMS_ID", "fakekms")
    capabilities = {
        "algorithms": ["AES256", "RSA2048"],
        "operations": [
            "generate",
            "rotate",
            "import_material",
            "export_material",
            "delete",
        ],
    }

    def __init__(self):
        self._dir = None
        self._reg = {}
        try:
            with open(_SENTINEL, "w") as fh:
                fh.write("loaded\n")
        except OSError:
            pass

    def configure(self, data_dir):
        self._dir = data_dir
        path = os.path.join(data_dir, _REG)
        try:
            with open(path) as fh:
                self._reg = json.load(fh)
        except (OSError, ValueError):
            self._reg = {}

    def _save(self):
        assert self._dir is not None
        tmp = os.path.join(self._dir, _REG + ".tmp")
        with open(tmp, "w") as fh:
            json.dump(self._reg, fh)
        os.replace(tmp, os.path.join(self._dir, _REG))

    def _log_delete(self, handle):
        with open(os.path.join(self._dir, _DELETE_LOG), "a") as fh:
            fh.write(handle + "\n")

    def _validate(self, algorithm, public_key, material):
        if algorithm == "AES256":
            raw = base64.b64decode(material, validate=True)
            if len(raw) != 32:
                raise ValueError("bad aes length")
            if public_key is not None:
                raise ValueError("aes public must be null")
            return None
        if algorithm == "RSA2048":
            priv = serialization.load_pem_private_key(
                material.encode(), password=None
            )
            if not isinstance(priv, rsa.RSAPrivateKey) or priv.key_size != 2048:
                raise ValueError("not rsa2048")
            if public_key is not None:
                pub = serialization.load_pem_public_key(public_key.encode())
                a = priv.public_key().public_bytes(
                    serialization.Encoding.DER,
                    serialization.PublicFormat.SubjectPublicKeyInfo,
                )
                b = pub.public_bytes(
                    serialization.Encoding.DER,
                    serialization.PublicFormat.SubjectPublicKeyInfo,
                )
                if a != b:
                    raise ValueError("pub mismatch")
            return priv
        raise ValueError("bad algorithm")

    def _mint(self, algorithm, public_key, material):
        import uuid

        if _fail_for("generate") or _fail_for("rotate") or _fail_for(
            "import_material"
        ):
            raise RuntimeError("BOOM backend exploded near handle secret-xyz")
        self._validate(algorithm, public_key, material)
        handle = "fh-" + uuid.uuid4().hex
        if algorithm == "RSA2048" and public_key is None:
            priv = serialization.load_pem_private_key(
                material.encode(), password=None
            )
            public_key = priv.public_key().public_bytes(
                serialization.Encoding.PEM,
                serialization.PublicFormat.SubjectPublicKeyInfo,
            ).decode()
        self._reg[handle] = {
            "algorithm": algorithm,
            "public_key": public_key,
            "material": material,
        }
        self._save()
        return {
            "handle": handle,
            "public_key": public_key,
            "encrypted_material": "fakeblob:" + handle,
        }

    def generate(self, algorithm):
        if algorithm == "AES256":
            material = base64.b64encode(os.urandom(32)).decode()
            public_key = None
        else:
            priv = rsa.generate_private_key(public_exponent=65537, key_size=2048)
            material = priv.private_bytes(
                serialization.Encoding.PEM,
                serialization.PrivateFormat.PKCS8,
                serialization.NoEncryption(),
            ).decode()
            public_key = priv.public_key().public_bytes(
                serialization.Encoding.PEM,
                serialization.PublicFormat.SubjectPublicKeyInfo,
            ).decode()
        return self._mint(algorithm, public_key, material)

    def rotate(self, algorithm):
        return self.generate(algorithm)

    def import_material(self, algorithm, public_key, material):
        return self._mint(algorithm, public_key, material)

    def export_material(self, handle):
        if _fail_for("export_material"):
            raise RuntimeError("BOOM export failure for " + handle)
        meta = self._reg.get(handle)
        if meta is None:
            raise RuntimeError("unknown backend handle " + handle)
        return {
            "public_key": meta["public_key"],
            "encrypted_material": meta["material"],
        }

    def delete(self, handle):
        if _fail_for("delete"):
            raise RuntimeError("BOOM delete failure")
        self._reg.pop(handle, None)
        if self._dir is not None:
            self._save()
            self._log_delete(handle)


def factory():
    mode = os.environ.get("FAKEKMS_LOAD", "ok")
    if mode == "raise":
        raise RuntimeError("BOOM factory failed")
    return FakeKMS()

